def parse_blocks(t):
 # capture input/output using dimensions label and line data
 blocks=[]
 for m in re.finditer(r'(?:Demo pair \d+ input|Demo pair \d+ output) \((\d+)x(\d+)\):\n(.*?)(?=\n\n|\Z)',t,re.S):
  h,w=map(int,m.group(1,2)); body=m.group(3).strip(); g=[[int(v) for v in row.split()] for row in body.splitlines()]
  blocks.append((h,w,g))
 return blocks
parsed={i:parse_blocks(t) for i,t in texts.items()}
[(i,[(x,y,len(g),len(g[0])) for x,y,g in blocks]) for i,blocks in parsed.items()]

def parse_blocks(t):
 blocks=[]
 for m in re.finditer(r'(Demo pair \d+ (?:input|output)) \((\d+)x(\d+)\):\n',t):
  h,w=map(int,m.group(2,3)); body=t[m.end():].splitlines()[:h]; g=[[int(v) for v in row.split()] for row in body]
  blocks.append((m.group(1),h,w,g))
 return blocks
parsed={i:parse_blocks(t) for i,t in texts.items()}
